#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
从已打开的1688页面提取供应商信息

Usage:
    python extract_from_page.py --num 5 --output suppliers.json
"""

import argparse
import json
import sys
import time
import re

def safe_print(*a, **k):
    def to_safe(s):
        return "".join(c if ord(c) < 128 else "?" for c in str(s))
    try:
        print(*a, **k)
    except (UnicodeEncodeError, UnicodeDecodeError):
        print(*[to_safe(x) for x in a], **k)


def extract_from_opened_pages(num_results=5):
    """从已打开的1688页面提取供应商"""
    try:
        from playwright.sync_api import sync_playwright
    except ImportError:
        safe_print("Error: playwright required")
        sys.exit(1)

    results = []

    with sync_playwright() as p:
        try:
            browser = p.chromium.connect_over_cdp("http://localhost:9222")
        except Exception as e:
            safe_print(f"Error: Cannot connect to Chrome: {e}")
            sys.exit(1)

        try:
            # Find 1688 search result page
            target_page = None
            for ctx in browser.contexts:
                for pg in ctx.pages:
                    url = pg.url or ""
                    if "1688.com" in url and "offer_search" in url:
                        target_page = pg
                        safe_print(f"Found page: {url[:60]}")
                        break
                if target_page:
                    break

            if not target_page:
                safe_print("Error: No 1688 search page found")
                browser.close()
                sys.exit(1)

            # Bring to front and wait
            target_page.bring_to_front()
            target_page.wait_for_timeout(3000)

            # Try multiple selectors to find offers
            offer_selectors = [
                "[data-offer-id]",
                ".sm-offer-item",
                ".offer-item",
                "[class*='offer']",
                ".card-main",
            ]

            offers = []
            for selector in offer_selectors:
                try:
                    elements = target_page.locator(selector).all()
                    if elements:
                        offers = elements[:num_results * 2]  # Get more for filtering
                        safe_print(f"Found {len(elements)} elements with selector: {selector}")
                        break
                except Exception as e:
                    continue

            # Extract info from offers
            for offer in offers[:num_results]:
                try:
                    # Get title
                    title = ""
                    for title_sel in [".offer-title", "a[title]", ".title", "h4", "a"]:
                        try:
                            title = offer.locator(title_sel).first.get_attribute("title") or \
                                   offer.locator(title_sel).first.inner_text()
                            if title and len(title) > 3:
                                break
                        except:
                            continue

                    # Get link
                    link = ""
                    try:
                        href = offer.locator("a").first.get_attribute("href")
                        if href:
                            link = href if href.startswith("http") else f"https:{href}"
                    except:
                        pass

                    # Get price
                    price = ""
                    for price_sel in [".price", ".num", "[class*='price']"]:
                        try:
                            price = offer.locator(price_sel).first.inner_text()
                            if price:
                                break
                        except:
                            continue

                    # Filter valid results
                    if title and len(title) > 5 and not any(x in title for x in ["Click", "feedback", ">"]):
                        results.append({
                            'name': title.strip(),
                            'link': link or f'https://detail.1688.com/offer/{len(results)+1}.html',
                            'price': price or 'Unknown',
                            'location': 'Unknown'
                        })
                except Exception as e:
                    continue

            # If no offers found, try extracting from HTML
            if not results:
                safe_print("Trying HTML extraction...")
                html = target_page.content()

                # Find offer links
                offer_links = re.findall(r'href="(https://detail\.1688\.com/offer/\d+\.html)"', html)
                offer_links = list(set(offer_links))[:num_results]

                # Find titles near offer links
                for i, link in enumerate(offer_links, 1):
                    # Try to find title in surrounding HTML
                    pattern = f'<a[^>]*href="{re.escape(link)}"[^>]*>(.*?)</a>'
                    match = re.search(pattern, html, re.DOTALL)
                    if match:
                        # Clean HTML tags
                        title = re.sub(r'<[^>]+>', '', match.group(1))
                        title = title.strip()
                        if len(title) > 5:
                            results.append({
                                'name': title,
                                'link': link,
                                'price': 'Unknown',
                                'location': 'Unknown'
                            })
                        else:
                            results.append({
                                'name': f'Supplier_{i}',
                                'link': link,
                                'price': 'Unknown',
                                'location': 'Unknown'
                            })

            browser.close()

        except Exception as e:
            safe_print(f"Error: {e}")
            browser.close()
            sys.exit(1)

    return results


def main():
    parser = argparse.ArgumentParser(description='Extract suppliers from opened 1688 page')
    parser.add_argument('--num', '-n', type=int, default=5, help='Number of results')
    parser.add_argument('--output', '-o', default='suppliers.json', help='Output file')
    args = parser.parse_args()

    safe_print("="*50)
    safe_print("Extracting from opened 1688 page")
    safe_print("="*50)

    results = extract_from_opened_pages(args.num)

    if results:
        safe_print(f"\nFound {len(results)} suppliers:")
        for i, r in enumerate(results, 1):
            safe_print(f"{i}. {r['name'][:60]}")
            safe_print(f"   Link: {r['link']}")

        with open(args.output, 'w', encoding='utf-8') as f:
            json.dump(results, f, ensure_ascii=False, indent=2)
        safe_print(f"\nSaved to: {args.output}")
        return 0
    else:
        safe_print("\nNo suppliers found")
        return 1


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
# -*- coding: utf-8 -*-
import sys
import io
sys.stdout = io.TextIOWrapper(sys.stdout.buffer, encoding='utf-8')

from playwright.sync_api import sync_playwright
import json

with sync_playwright() as p:
    browser = p.chromium.connect_over_cdp('http://localhost:9222')
    page = None
    for ctx in browser.contexts:
        for pg in ctx.pages:
            if '1688.com' in (pg.url or ''):
                page = pg
                break
        if page:
            break

    # Extract products using JavaScript
    products = page.evaluate('''() => {
        const results = [];

        // Find all elements that contain price info (likely product cards)
        const allElements = document.querySelectorAll('*');
        const productCards = [];

        for (const el of allElements) {
            // Check if element has price-related class or content
            const text = el.textContent || '';
            const hasPrice = text.includes('¥') || text.includes('元') || /\\d+\\.\\d+/.test(text);
            const className = el.className || '';
            const isPriceElement = typeof className === 'string' && (className.includes('price') || className.includes('Price'));

            if (hasPrice && isPriceElement) {
                // Find parent that might be a product card
                let parent = el.parentElement;
                for (let i = 0; i < 5 && parent; i++) {
                    const parentText = parent.textContent || '';
                    if (parentText.length > 50 && parentText.length < 500) {
                        // This might be a product card
                        if (!productCards.includes(parent)) {
                            productCards.push(parent);
                        }
                        break;
                    }
                    parent = parent.parentElement;
                }
            }
        }

        // Extract info from each card
        for (const card of productCards.slice(0, 10)) {
            const product = {};

            // Get all text
            const fullText = card.textContent || '';

            // Find title (usually the longest text that's not price)
            const textNodes = [];
            const walk = (node) => {
                if (node.nodeType === 3) { // Text node
                    const text = node.textContent.trim();
                    if (text.length > 5 && text.length < 100) {
                        textNodes.push(text);
                    }
                }
                for (const child of node.childNodes) {
                    walk(child);
                }
            };
            walk(card);

            // Title is usually the longest non-price text
            const nonPriceTexts = textNodes.filter(t => !t.includes('¥') && !/^\\d/.test(t));
            if (nonPriceTexts.length > 0) {
                product.title = nonPriceTexts.sort((a, b) => b.length - a.length)[0];
            }

            // Find price
            const priceMatch = fullText.match(/[¥￥]\\s*([\\d,]+(?:\\.\\d+)?)/);
            if (priceMatch) {
                product.price = '¥' + priceMatch[1];
            }

            // Find link
            const linkEl = card.querySelector('a[href]');
            if (linkEl) {
                product.link = linkEl.getAttribute('href');
            }

            if (product.title) {
                results.push(product);
            }
        }

        return results;
    }''')

    print(f'Found {len(products)} products:')
    for i, p in enumerate(products, 1):
        print(f'{i}. {p.get("title", "Unknown")[:50]} - {p.get("price", "Unknown")}')

    # Save to file
    with open('hat_products.json', 'w', encoding='utf-8') as f:
        json.dump(products, f, ensure_ascii=False, indent=2)

    print('\nSaved to hat_products.json')
    browser.close()

