                        return firstName ? firstName.innerText.trim() : 'Unknown';
                    }}
                    return null;
                }}
            ''')

            if clicked:
                safe_print(f"  已点击联系人: {clicked}")
            else:
                safe_print("  未找到联系人")
                browser.close()
                return None

            time.sleep(3)  # 等待聊天内容加载

            # 步骤3: 获取对话记录
            safe_print("\n步骤3: 获取对话记录...")

            messages = []
            for frame_idx, frame in enumerate(wangwang_page.frames):
                try:
                    msg_elements = frame.query_selector_all('.message-item, .msg-item, [class*="message"], [class*="bubble"]')

                    for msg in msg_elements[-10:]:  # 最近10条
                        try:
                            text = msg.inner_text() or ""
                            if text.strip():
                                # 判断方向
                                is_mine = msg.evaluate('el => el.classList.contains("mine") || el.classList.contains("self")')
                                messages.append({
                                    'text': text[:200],
                                    'direction': 'out' if is_mine else 'in'
                                })
                        except:
                            pass
                except:
                    pass

            safe_print(f"  获取到 {len(messages)} 条消息")

            if messages:
                safe_print("\n  最新消息:")
                for msg in messages[-5:]:
                    direction = "→" if msg['direction'] == 'out' else "←"
                    safe_print(f"    {direction} {msg['text'][:60]}")

            # 步骤4: 同步到数据库
            safe_print("\n步骤4: 同步到本地数据库...")

            db = load_database()
            supplier = find_supplier(db, supplier_name)

            if supplier:
                # 更新状态
                has_reply = any(m['direction'] == 'in' for m in messages)
                if has_reply:
                    supplier['status'] = '已回复'
                elif messages:
                    supplier['status'] = '已联系'

                # 添加新消息
                for msg in messages:
                    exists = False
                    for h in supplier['history']:
                        if h['message'] == msg['text']:
                            exists = True
                            break

                    if not exists:
                        supplier['history'].append({
                            'time': datetime.now().isoformat(),
                            'message': msg['text'],
                            'direction': msg['direction']
                        })

                save_database(db)
                safe_print(f"  ✓ 已同步到供应商: {supplier_name}")
            else:
                safe_print(f"  ⚠ 本地数据库中未找到供应商: {supplier_name}")

            browser.close()
            return messages

        except Exception as e:
            safe_print(f"Error: {e}")
            import traceback
            safe_print(traceback.format_exc())
            browser.close()
            return None

if __name__ == "__main__":
    import argparse

    parser = argparse.ArgumentParser(description='搜索旺旺联系人并查看最新信息')
    parser.add_argument('--name', '-n', required=True, help='供应商名称')
    args = parser.parse_args()

    search_and_get_chat(args.name)

#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
在已打开的旺旺聊天页面发送消息

使用方法:
    python send_chat_message.py --message "消息内容"
"""

import sys
import io
sys.stdout = io.TextIOWrapper(sys.stdout.buffer, encoding='utf-8')

import argparse
import time

def safe_print(text):
    try:
        print(text)
    except:
        print(str(text).encode('utf-8', errors='replace').decode('utf-8', errors='replace'))

def send_chat_message(message):
    """
    在已打开的旺旺聊天页面发送消息
    """
    try:
        from playwright.sync_api import sync_playwright
    except ImportError:
        safe_print("Error: pip install playwright")
        return False

    with sync_playwright() as p:
        try:
            browser = p.chromium.connect_over_cdp("http://localhost:9222")
        except Exception as e:
            safe_print(f"Error connecting to browser: {e}")
            return False

        try:
            # 找到聊天页面
            chat_page = None
            for ctx in browser.contexts:
                for pg in ctx.pages:
                    if "air.1688.com" in pg.url and "def_cbu_web_im" in pg.url:
                        chat_page = pg
                        safe_print(f"Found chat page: {pg.url[:80]}...")
                        break
                if chat_page:
                    break

            if not chat_page:
                safe_print("Error: No chat page found. Please click Wangwang icon first.")
                browser.close()
                return False

            # 切换到聊天页面
            chat_page.bring_to_front()
            time.sleep(2)

            # 截图聊天页面
            timestamp = time.strftime("%Y%m%d_%H%M%S")
            chat_screenshot = f"chat_before_{timestamp}.png"
            chat_page.screenshot(path=chat_screenshot, full_page=False)
            safe_print(f"Chat screenshot saved: {chat_screenshot}")

            # 查找输入框 - 在iframe中
            safe_print("Looking for chat input...")

            # 先尝试在主页面查找
            input_selectors = [
                'pre[contenteditable="true"]',
                '[contenteditable="true"]',
                'textarea',
                'input[type="text"]',
                '.edit',
            ]

            input_found = False

            # 在所有frames中查找
            for frame in chat_page.frames:
                for sel in input_selectors:
                    try:
                        element = frame.locator(sel).first
                        if element.is_visible():
                            safe_print(f"Found input in frame: {sel}")

                            # 点击输入框
                            element.click()
                            time.sleep(0.5)

                            # 输入消息
                            element.fill(message)
                            safe_print(f"Message entered: {message}")
                            time.sleep(1)

                            # 查找发送按钮
                            send_selectors = [
                                'button:has-text("发送")',
                                'text=发送',
                                '[class*="send"]',
                                'button.send',
                            ]

                            for send_sel in send_selectors:
                                try:
                                    send_btn = frame.locator(send_sel).first
                                    if send_btn.is_visible():
                                        safe_print(f"Found send button: {send_sel}")
                                        send_btn.click()
                                        safe_print("✓ Message sent!")
                                        input_found = True
                                        time.sleep(2)
                                        break
                                except:
                                    continue

                            if not input_found:
                                # 尝试按Enter发送
                                element.press("Enter")
                                safe_print("✓ Message sent (Enter key)")
                                input_found = True
                                time.sleep(2)

                            break
                    except Exception as e:
                        continue

                if input_found:
                    break

            if not input_found:
                safe_print("Warning: Could not find chat input")
                # 尝试使用JavaScript
                try:
                    safe_print("Trying JavaScript method...")
                    chat_page.evaluate(f'''
                        () => {{
                            const inputs = document.querySelectorAll('pre[contenteditable="true"], [contenteditable="true"], textarea');
                            if (inputs.length > 0) {{
                                const input = inputs[0];
                                input.focus();
                                input.innerText = "{message}";
                                input.dispatchEvent(new Event('input', {{ bubbles: true }}));

                                // 查找发送按钮
                                const sendBtns = document.querySelectorAll('button');
                                for (const btn of sendBtns) {{
                                    if (btn.textContent.includes('发送')) {{
                                        btn.click();
                                        return true;
                                    }}
                                }}
                                return false;
                            }}
                            return false;
                        }}
                    ''')
                    safe_print("JavaScript method executed")
                    time.sleep(2)
                except Exception as e:
                    safe_print(f"JavaScript method failed: {e}")

            # 截图发送后的页面
            after_screenshot = f"chat_after_{timestamp}.png"
            chat_page.screenshot(path=after_screenshot, full_page=False)
            safe_print(f"After screenshot saved: {after_screenshot}")

            browser.close()
            return input_found

        except Exception as e:
            safe_print(f"Error: {e}")
            import traceback
            safe_print(traceback.format_exc())
            browser.close()
            return False

def main():
    parser = argparse.ArgumentParser(description='在旺旺聊天页面发送消息')
    parser.add_argument('--message', '-m', required=True, help='要发送的消息')
    args = parser.parse_args()

    safe_print("="*60)
    safe_print("发送旺旺消息")
    safe_print("="*60)
    safe_print(f"消息: {args.message}")
    safe_print("="*60)

    success = send_chat_message(args.message)

    if success:
        safe_print("\n✓ 消息发送成功")
        return 0
    else:
        safe_print("\n✗ 消息发送失败")
        return 1

if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
逐个同步所有196个旺旺联系人 - 从第一个到最后一个
"""

import sys
import io
sys.stdout = io.TextIOWrapper(sys.stdout.buffer, encoding='utf-8')

import json
import time
from datetime import datetime
from pathlib import Path

DATABASE_FILE = "suppliers_database.json"

def safe_print(text):
    try:
        print(text)
    except:
        print(str(text).encode('utf-8', errors='replace').decode('utf-8', errors='replace'))

def load_database():
    db_path = Path(DATABASE_FILE)
    if db_path.exists():
        with open(db_path, 'r', encoding='utf-8') as f:
            return json.load(f)
    return {'suppliers': [], 'last_updated': datetime.now().isoformat()}

def save_database(data):
    data['last_updated'] = datetime.now().isoformat()
    with open(DATABASE_FILE, 'w', encoding='utf-8') as f:
        json.dump(data, f, ensure_ascii=False, indent=2)

def find_or_create_supplier(db, name):
    for s in db['suppliers']:
        if s['name'] == name:
            return s

    supplier = {
        'id': len(db['suppliers']) + 1,
        'name': name,
        'product': '帽子',
        'link': '',
        'price': 'Unknown',
        'contact': '',
        'notes': '从旺旺同步',
        'status': '待联系',
        'created_at': datetime.now().isoformat(),
        'history': []
    }
    db['suppliers'].append(supplier)
    return supplier

def sync_all_196_contacts():
    """同步所有196个联系人"""
    try:
        from playwright.sync_api import sync_playwright
    except ImportError:
        safe_print("Error: pip install playwright")
        return 0

    with sync_playwright() as p:
        try:
            browser = p.chromium.connect_over_cdp("http://localhost:9222")
        except Exception as e:
            safe_print(f"Error: Cannot connect to Chrome: {e}")
            return 0

        try:
            # 查找旺旺聊天页面
            wangwang_page = None
            for ctx in browser.contexts:
                for pg in ctx.pages:
                    if "air.1688.com" in pg.url and "def_cbu_web_im" in pg.url:
                        wangwang_page = pg
                        break
                if wangwang_page:
                    break

            if not wangwang_page:
                safe_print("旺旺聊天页面未找到")
                browser.close()
                return 0

            safe_print("="*60)
            safe_print("同步所有196个旺旺联系人")
            safe_print("="*60)

            wangwang_page.bring_to_front()
            time.sleep(2)

            # 找到包含联系人的frame
            target_frame = None
            for frame in wangwang_page.frames:
                try:
                    contacts_test = frame.query_selector_all('.conversation-item')
                    if len(contacts_test) > 0:
                        target_frame = frame
                        break
                except:
                    pass

            if not target_frame:
                safe_print("未找到包含联系人的frame")
                browser.close()
                return 0

            db = load_database()

            # 滚动到顶部
            safe_print("\n滚动到顶部...")
            target_frame.evaluate('''() => {
                const list = document.querySelector('[style*="overflow: auto"]');
                if (list) list.scrollTop = 0;
            }''')
            time.sleep(3)

            # 获取所有联系人
            safe_print("获取所有联系人...")

            all_contacts = []
            last_scroll_top = -1
            same_count = 0

            for i in range(200):
                contacts = target_frame.evaluate('''() => {
                    const results = [];
                    const items = document.querySelectorAll('.conversation-item');
                    items.forEach(item => {
                        const nameEl = item.querySelector('.name');
                        const timeEl = item.querySelector('.time');
                        const descEl = item.querySelector('.desc');

                        if (nameEl) {
                            const rect = item.getBoundingClientRect();
                            results.push({
                                name: nameEl.innerText.trim(),
                                time: timeEl ? timeEl.innerText.trim() : '',
                                desc: descEl ? descEl.innerText.trim() : '',
                                top: rect.top
                            });
                        }
                    });
                    return results;
                }''')

                for c in contacts:
                    if not any(existing['name'] == c['name'] for existing in all_contacts):
                        all_contacts.append(c)

                scroll_info = target_frame.evaluate('''() => {
                    const list = document.querySelector('[style*="overflow: auto"]');
                    if (list) {
                        return {
                            scrollTop: list.scrollTop,
                            scrollHeight: list.scrollHeight
                        };
                    }
                    return null;
                }''')

                if scroll_info:
                    if scroll_info['scrollTop'] == last_scroll_top:
                        same_count += 1
                        if same_count >= 3:
                            break
                    else:
                        same_count = 0
                        last_scroll_top = scroll_info['scrollTop']

                target_frame.evaluate('''() => {
                    const list = document.querySelector('[style*="overflow: auto"]');
                    if (list) list.scrollTop += 200;
                }''')

                time.sleep(0.3)

            safe_print(f"找到 {len(all_contacts)} 个联系人")
            safe_print("="*60)

            # 从第一个到最后一个逐个同步
            synced_count = 0

            for i, contact in enumerate(all_contacts, 1):
                name = contact['name']

                safe_print(f"\n[{i}/{len(all_contacts)}] {name[:40]}")

                try:
                    # 点击联系人
                    clicked = target_frame.evaluate(f'''
                        (contactName) => {{
                            const items = document.querySelectorAll('.conversation-item');
                            for (const item of items) {{
                                const nameEl = item.querySelector('.name');
                                if (nameEl && nameEl.innerText.trim() === contactName) {{
                                    item.scrollIntoView({{behavior: 'smooth', block: 'center'}});
                                    setTimeout(() => item.click(), 300);
                                    return true;
                                }}
                            }}
                            return false;
                        }}
                    ''', name)

                    if clicked:
                        time.sleep(3)

                        # 获取对话
                        messages = wangwang_page.evaluate('''() => {
                            const results = [];
                            const msgElements = document.querySelectorAll('.message-item, .msg-item, .bubble, [class*="message"]');
                            msgElements.forEach(msg => {
                                const text = msg.innerText || '';
                                if (text.trim() && text.length > 5) {
                                    const className = msg.className || '';
                                    const isMine = className.includes('mine') || className.includes('self');

                                    const exists = results.find(r => r.text === text.substring(0, 200));
                                    if (!exists) {
                                        results.push({
                                            text: text.substring(0, 200),
                                            direction: isMine ? 'out' : 'in'
                                        });
                                    }
                                }
                            });
                            return results.slice(-3);
                        }''')

                        # 同步到数据库
                        supplier = find_or_create_supplier(db, name)

                        has_reply = any(m['direction'] == 'in' for m in messages)
                        if has_reply:
                            supplier['status'] = '已回复'
                        elif messages:
                            supplier['status'] = '已联系'

                        for msg in messages:
                            exists = False
                            for h in supplier['history']:
                                if h['message'] == msg['text']:
                                    exists = True
                                    break

                            if not exists:
                                supplier['history'].append({
                                    'time': datetime.now().isoformat(),
                                    'message': msg['text'],
                                    'direction': msg['direction']
                                })

                        synced_count += 1
                        safe_print(f"  ✓ 同步完成 ({len(messages)} 条消息)")
                    else:
                        safe_print("  ✗ 点击失败")

                except Exception as e:
                    safe_print(f"  ✗ 错误: {e}")

                if i < len(all_contacts):
                    time.sleep(1)

            # 保存数据库
            save_database(db)

            safe_print("\n" + "="*60)
            safe_print(f"完成: 同步 {synced_count}/{len(all_contacts)} 个联系人")
            safe_print(f"数据库现在共有 {len(db['suppliers'])} 家供应商")
            safe_print("="*60)

            browser.close()
            return synced_count

        except Exception as e:
            safe_print(f"错误: {e}")
            import traceback
            safe_print(traceback.format_exc())
            browser.close()
            return 0

if __name__ == "__main__":
    sync_all_196_contacts()

